def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    objects = []

    # Extract separate 4-connected objects, retaining each object's color.
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            color = grid[r][c]
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                x, y = stack.pop()
                cells.append((x, y))
                for nx, ny in ((x - 1, y), (x + 1, y), (x, y - 1), (x, y + 1)):
                    if (0 <= nx < h and 0 <= ny < w and
                            (nx, ny) not in seen and grid[nx][ny] == color):
                        seen.add((nx, ny))
                        stack.append((nx, ny))
            objects.append([color, cells])

    # Objects farther right move first, sliding right until blocked.
    objects.sort(key=lambda obj: max(c for _, c in obj[1]), reverse=True)
    for i, (color, cells) in enumerate(objects):
        occupied = {cell for _, other in objects[:i] for cell in other}
        while True:
            shifted = [(r, c + 1) for r, c in cells]
            if any(c >= w or (r, c) in occupied for r, c in shifted):
                break
            cells = shifted
        objects[i][1] = cells

    result = [[0] * w for _ in range(h)]
    for color, cells in objects:
        for r, c in cells:
            result[r][c] = color
    return result
